1	import { app } from 'electron'
2	import { randomUUID } from 'node:crypto'
3	import { EventEmitter } from 'node:events'
4	import { existsSync, readFileSync, writeFileSync, mkdirSync, renameSync } from 'node:fs'
5	import { writeFile, mkdir, rename } from 'node:fs/promises'
6	import path from 'node:path'
7	
8	// AI 챗 대화 영속화 — 재시작해도 대화가 남고, 여러 스레드를 오가며 이어갈 수 있게 한다.
9	// userData/ai-chats.json 하나에 모든 대화를 담고, 원자적(tmp+rename) 디바운스 저장.
10	
11	export interface StoredMessage { role: 'user' | 'assistant'; content: string }
12	
13	// 폴더 색(외피 탭 그룹과 동일 팔레트) — 좁은 폭에서 폴더를 색 점으로 구분한다.
14	export const FOLDER_COLORS = ['blue', 'red', 'green', 'yellow', 'purple', 'pink', 'orange', 'gray'] as const
15	export type FolderColor = (typeof FOLDER_COLORS)[number]
16	function isFolderColor(c: unknown): c is FolderColor {
17	  return typeof c === 'string' && (FOLDER_COLORS as readonly string[]).includes(c)
18	}
19	
20	export interface ChatFolder { id: string; name: string; createdAt: number; color: FolderColor; emoji?: string }
21	export interface Conversation {
22	  id: string
23	  title: string
24	  createdAt: number
25	  updatedAt: number
26	  messages: StoredMessage[]
27	  folderId?: string | null
28	  tags?: string[]
29	  pinned?: boolean
30	  summary?: string    // 접힌(요약된) 앞부분 대화 — 압축 기능
31	  foldCount?: number  // 앞에서 몇 개 메시지가 요약으로 접혔는지
32	}
33	export interface ConversationSummary {
34	  id: string
35	  title: string
36	  updatedAt: number
37	  messageCount: number
38	  folderId: string | null
39	  tags: string[]
40	  pinned: boolean
41	}
42	
43	export const conversationEvents = new EventEmitter()
44	
45	const MAX_CONVERSATIONS = 100
46	const MAX_MESSAGES = 200
47	const MAX_TAGS = 8
48	const MAX_TAG_LEN = 24
49	
50	let cache: Conversation[] | null = null
51	let folderCache: ChatFolder[] | null = null
52	let writeTimer: NodeJS.Timeout | null = null
53	let dirty = false
54	let quitHooked = false
55	
56	function filePath(): string {
57	  return path.join(app.getPath('userData'), 'ai-chats.json')
58	}
59	
60	function isValidConv(c: unknown): c is Conversation {
61	  if (!c || typeof c !== 'object') return false
62	  const o = c as Record<string, unknown>
63	  return typeof o.id === 'string' && Array.isArray(o.messages)
64	}
65	
66	function isValidFolder(f: unknown): f is ChatFolder {
67	  if (!f || typeof f !== 'object') return false
68	  const o = f as Record<string, unknown>
69	  return typeof o.id === 'string' && typeof o.name === 'string'
70	}
71	
72	export function initConversations(): void {
73	  // 종료 시 디바운스 대기 중이던 저장을 동기 flush(정상 종료 데이터 손실 방지).
74	  if (!quitHooked) { quitHooked = true; try { app.on('before-quit', flushConversations) } catch { /* ignore */ } }
75	  if (cache !== null) return
76	  try {
77	    if (existsSync(filePath())) {
78	      const raw = JSON.parse(readFileSync(filePath(), 'utf-8')) as { conversations?: unknown; folders?: unknown }
79	      cache = Array.isArray(raw?.conversations) ? raw.conversations.filter(isValidConv) : []
80	      folderCache = Array.isArray(raw?.folders)
81	        ? raw.folders.filter(isValidFolder).map((f) => {
82	            const o = f as { color?: unknown; emoji?: unknown }
83	            return {
84	              ...f,
85	              color: isFolderColor(o.color) ? o.color : 'gray',
86	              emoji: typeof o.emoji === 'string' && o.emoji ? o.emoji : undefined,
87	            }
88	          })
89	        : []
90	    } else {
91	      cache = []
92	      folderCache = []
93	    }
94	  } catch (err) {
95	    console.warn('[ai] conversations load failed', err)
96	    // 손상 파일을 .bak 으로 보존한 뒤 빈 상태로 시작한다 — 다음 저장이 원본을 영구히 덮어써
97	    // 복구 불가능해지는 것을 막는다.
98	    try { if (existsSync(filePath())) renameSync(filePath(), filePath() + '.corrupt.bak') } catch { /* ignore */ }
99	    cache = []
100	    folderCache = []
101	  }
102	}
103	
104	function all(): Conversation[] {
105	  if (cache === null) initConversations()
106	  return cache ?? []
107	}
108	
109	function allFolders(): ChatFolder[] {
110	  if (folderCache === null) initConversations()
111	  return folderCache ?? []
112	}
113	
114	function schedulePersist(): void {
115	  dirty = true
116	  if (writeTimer) clearTimeout(writeTimer)
117	  writeTimer = setTimeout(() => { void persist() }, 300)
118	}
119	
120	async function persist(): Promise<void> {
121	  try {
122	    await mkdir(path.dirname(filePath()), { recursive: true })
123	    const tmp = filePath() + '.tmp'
124	    await writeFile(tmp, JSON.stringify({ version: 1, conversations: all(), folders: allFolders() }), 'utf-8')
125	    await rename(tmp, filePath())
126	    dirty = false
127	  } catch (err) {
128	    console.warn('[ai] conversations persist failed', err)
129	  }
130	}
131	
132	// 종료 시 동기 저장 — 디바운스 대기 중이던 마지막 대화가 유실되지 않도록.
133	export function flushConversations(): void {
134	  if (writeTimer) { clearTimeout(writeTimer); writeTimer = null }
135	  if (!dirty) return
136	  try {
137	    mkdirSync(path.dirname(filePath()), { recursive: true })
138	    // 원자적 쓰기(tmp+rename) — 종료 중 프로세스가 죽어도 ai-chats.json 이 잘려 전체 대화가 날아가지 않도록.
139	    const tmp = filePath() + '.tmp'
140	    writeFileSync(tmp, JSON.stringify({ version: 1, conversations: all(), folders: allFolders() }), 'utf-8')
141	    renameSync(tmp, filePath())
142	    dirty = false
143	  } catch (err) {
144	    console.warn('[ai] conversations flush failed', err)
145	  }
146	}
147	
148	function summaryOf(c: Conversation): ConversationSummary {
149	  return {
150	    id: c.id, title: c.title || '새 대화', updatedAt: c.updatedAt, messageCount: c.messages.length,
151	    folderId: c.folderId ?? null, tags: c.tags ?? [], pinned: c.pinned ?? false,
152	  }
153	}
154	
155	function emitChanged(): void {
156	  conversationEvents.emit('changed', listConversations())
157	}
158	
159	function emitFolders(): void {
160	  conversationEvents.emit('folders', listFolders())
161	}
162	
163	export function listConversations(): ConversationSummary[] {
164	  return all().slice().sort((a, b) => {
165	    // 고정 대화 먼저, 그다음 최근성
166	    const pa = a.pinned ? 1 : 0, pb = b.pinned ? 1 : 0
167	    if (pa !== pb) return pb - pa
168	    return b.updatedAt - a.updatedAt
169	  }).map(summaryOf)
170	}
171	
172	export function getConversation(id: string): Conversation | null {
173	  return all().find((c) => c.id === id) ?? null
174	}
175	
176	export function setConversationPinned(id: string, pinned: boolean): void {
177	  const c = all().find((x) => x.id === id)
178	  if (!c) return
179	  c.pinned = !!pinned // updatedAt 은 유지 — 고정은 정렬 그룹만 바꾸고 최근성은 보존
180	  schedulePersist()
181	  emitChanged()
182	}
183	
184	export interface ConvSearchHit { id: string; snippet: string | null }
185	
186	// 매칭 위치 주변의 짧은 본문 발췌(하이라이트용) — 앞뒤 …
187	function snippetAround(text: string, q: string): string {
188	  const flat = text.replace(/\s+/g, ' ')
189	  const idx = flat.toLowerCase().indexOf(q.toLowerCase())
190	  if (idx < 0) return ''
191	  const start = Math.max(0, idx - 30)
192	  const end = Math.min(flat.length, idx + q.length + 40)
193	  return (start > 0 ? '…' : '') + flat.slice(start, end).trim() + (end < flat.length ? '…' : '')
194	}
195	
196	// 제목 + 메시지 본문까지 검색. 제목만 매칭이면 snippet=null(제목 하이라이트로 충분),
197	// 본문 매칭이면 그 위치 발췌를 함께 반환(어디서 맞았는지 보여주기).
198	export function searchConversations(query: string): ConvSearchHit[] {
199	  // 쿼리·본문 모두 공백을 같은 방식으로 정규화(collapse)해서 매칭한다 — 그러지 않으면 "foo bar"(한 칸)가
200	  // 본문 "foo\nbar"/"foo  bar" 를 놓치거나, 매칭돼도 snippet 이 '' 이 되어 결과에서 탈락하는 불일치가 생긴다.
201	  const q = String(query ?? '').trim().replace(/\s+/g, ' ').toLowerCase()
202	  if (!q) return []
203	  const out: ConvSearchHit[] = []
204	  for (const c of all()) {
205	    const titleHit = typeof c.title === 'string' && c.title.replace(/\s+/g, ' ').toLowerCase().includes(q)
206	    let contentHit = false
207	    let snippet: string | null = null
208	    for (const m of c.messages) {
209	      if (typeof m?.content === 'string' && m.content.replace(/\s+/g, ' ').toLowerCase().includes(q)) {
210	        contentHit = true
211	        snippet = snippetAround(m.content, q) || null // 매칭했으나 발췌가 비어도 결과에는 포함
212	        break
213	      }
214	    }
215	    if (titleHit || contentHit) out.push({ id: c.id, snippet: titleHit ? null : snippet })
216	  }
217	  return out
218	}
219	
220	function deriveTitle(messages: StoredMessage[]): string {
221	  const first = messages.find((m) => m.role === 'user' && m.content.trim())
222	  const t = (first?.content ?? '').replace(/\s+/g, ' ').trim()
223	  if (!t) return '새 대화'
224	  return t.length > 40 ? t.slice(0, 40) + '…' : t
225	}
226	
227	// upsert — 렌더러가 한 번의 왕복이 끝날 때마다 스레드 전체를 저장.
228	// extra: 압축 상태(summary/foldCount)도 함께 영속화 → 재시작해도 접힌 상태 유지.
229	export function saveConversation(id: string, messages: StoredMessage[], extra?: { summary?: string; foldCount?: number }): ConversationSummary | null {
230	  const clean: StoredMessage[] = messages
231	    .filter((m) => (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string' && m.content.trim())
232	    .map((m) => ({ role: m.role, content: m.content }))
233	    .slice(-MAX_MESSAGES)
234	  if (clean.length === 0) return null
235	  // foldCount 는 저장되는 메시지 수를 넘지 않도록 클램프(필터/슬라이스로 개수가 줄 수 있음).
236	  const summary = typeof extra?.summary === 'string' ? extra.summary : undefined
237	  const foldCount = typeof extra?.foldCount === 'number' ? Math.max(0, Math.min(extra.foldCount, clean.length)) : undefined
238	  const now = Date.now()
239	  const list = all()
240	  const existing = list.find((c) => c.id === id)
241	  let conv: Conversation
242	  if (existing) {
243	    existing.messages = clean
244	    existing.updatedAt = now
245	    if (!existing.title || existing.title === '새 대화') existing.title = deriveTitle(clean)
246	    existing.summary = summary
247	    existing.foldCount = foldCount
248	    conv = existing
249	  } else {
250	    conv = { id, title: deriveTitle(clean), createdAt: now, updatedAt: now, messages: clean, summary, foldCount }
251	    list.push(conv)
252	    if (list.length > MAX_CONVERSATIONS) {
253	      // 고정 대화는 되도록 축출하지 않는다 — "고정=보존" 의미 보장.
254	      list.sort((a, b) => {
255	        const pa = a.pinned ? 1 : 0, pb = b.pinned ? 1 : 0
256	        if (pa !== pb) return pb - pa
257	        return b.updatedAt - a.updatedAt
258	      })
259	      let trimmed = list.slice(0, MAX_CONVERSATIONS)
260	      // 단, 고정이 상한을 꽉 채워 방금 저장한 새 대화가 잘려나갔다면(조용히 유실 — saveConversation 은
261	      // 성공을 반환) 가장 오래된 고정 하나를 대신 축출해 새 대화를 보존한다.
262	      if (!trimmed.some((x) => x.id === conv.id)) trimmed = [...trimmed.slice(0, MAX_CONVERSATIONS - 1), conv]
263	      cache = trimmed
264	    }
265	  }
266	  schedulePersist()
267	  emitChanged()
268	  return summaryOf(conv)
269	}
270	
271	export function renameConversation(id: string, title: string): void {
272	  const conv = all().find((c) => c.id === id)
273	  if (!conv) return
274	  conv.title = String(title ?? '').replace(/\s+/g, ' ').trim().slice(0, 80) || '새 대화'
275	  conv.updatedAt = Date.now()
276	  schedulePersist()
277	  emitChanged()
278	}
279	
280	export function deleteConversation(id: string): void {
281	  const list = all()
282	  const idx = list.findIndex((c) => c.id === id)
283	  if (idx < 0) return
284	  list.splice(idx, 1)
285	  schedulePersist()
286	  emitChanged()
287	}
288	
289	export function clearAllConversations(): void {
290	  cache = []
291	  schedulePersist()
292	  emitChanged()
293	}
294	
295	// ===== 폴더 (1단 평면) =====
296	
297	export function listFolders(): ChatFolder[] {
298	  return allFolders().slice() // 저장된 배열 순서 = 사용자 정렬 순서
299	}
300	
301	export function reorderFolders(orderedIds: string[]): void {
302	  const list = allFolders()
303	  const byId = new Map(list.map((f) => [f.id, f]))
304	  const next: ChatFolder[] = []
305	  for (const id of orderedIds) { const f = byId.get(id); if (f) { next.push(f); byId.delete(id) } }
306	  for (const f of list) { if (byId.has(f.id)) next.push(f) } // 누락분은 뒤에 보존
307	  folderCache = next
308	  schedulePersist()
309	  emitFolders()
310	}
311	
312	// 파일명 위생 처리(대화·보고서 내보내기 공용).
313	export function safeFileName(name: string): string {
314	  return name.replace(/[\\/:*?"<>|]/g, '_').replace(/\s+/g, ' ').trim().slice(0, 60) || 'export'
315	}
316	
317	// 다운로드 폴더에 마크다운 파일을 충돌 없이 기록(대화·보고서 내보내기 공용 — 다이얼로그/블롭 우회).
318	export async function writeDownloadMd(base: string, md: string): Promise<{ ok: boolean; path?: string }> {
319	  try {
320	    const dir = app.getPath('downloads')
321	    await mkdir(dir, { recursive: true })
322	    let file = path.join(dir, `${base}.md`)
323	    let n = 1
324	    while (existsSync(file)) { file = path.join(dir, `${base} (${n++}).md`) }
325	    await writeFile(file, md, 'utf-8')
326	    return { ok: true, path: file }
327	  } catch {
328	    return { ok: false }
329	  }
330	}
331	
332	// 대화 하나를 마크다운으로 (개별 내보내기)
333	export function conversationToMarkdown(conv: Conversation): string {
334	  const lines: string[] = [`# ${conv.title || '대화'}`, '']
335	  for (const m of conv.messages) {
336	    lines.push(`**${m.role === 'user' ? '나' : 'AI'}:**`, '', m.content, '', '---', '')
337	  }
338	  return lines.join('\n')
339	}
340	
341	// 여러 대화를 하나의 마크다운으로 (다중/폴더 내보내기)
342	export function conversationsToMarkdown(convs: Conversation[]): string {
343	  const lines: string[] = [`# 대화 내보내기 (${convs.length}개)`, '', '---', '']
344	  for (const c of convs) {
345	    lines.push(`## ${c.title || '대화'}`, '')
346	    for (const m of c.messages) lines.push(`**${m.role === 'user' ? '나' : 'AI'}:**`, '', m.content, '')
347	    lines.push('---', '')
348	  }
349	  return lines.join('\n')
350	}
351	
352	function pickFolderColor(): FolderColor {
353	  const used = new Set(allFolders().map((f) => f.color))
354	  const free = FOLDER_COLORS.find((c) => !used.has(c))
355	  return free ?? FOLDER_COLORS[allFolders().length % FOLDER_COLORS.length] ?? 'gray'
356	}
357	
358	export function createFolder(name: string, color?: FolderColor): ChatFolder | null {
359	  const n = String(name ?? '').replace(/\s+/g, ' ').trim().slice(0, 40)
360	  if (!n) return null
361	  const folder: ChatFolder = { id: randomUUID(), name: n, createdAt: Date.now(), color: isFolderColor(color) ? color : pickFolderColor() }
362	  allFolders().push(folder)
363	  schedulePersist()
364	  emitFolders()
365	  return folder
366	}
367	
368	export function setFolderColor(id: string, color: FolderColor): void {
369	  if (!isFolderColor(color)) return
370	  const f = allFolders().find((x) => x.id === id)
371	  if (!f) return
372	  f.color = color
373	  schedulePersist()
374	  emitFolders()
375	}
376	
377	export function setFolderEmoji(id: string, emoji: string): void {
378	  const f = allFolders().find((x) => x.id === id)
379	  if (!f) return
380	  const e = String(emoji ?? '').trim().slice(0, 8)
381	  f.emoji = e || undefined // 빈 문자열 = 아이콘 제거(색 점으로 복귀)
382	  schedulePersist()
383	  emitFolders()
384	}
385	
386	export function renameFolder(id: string, name: string): void {
387	  const f = allFolders().find((x) => x.id === id)
388	  if (!f) return
389	  f.name = String(name ?? '').replace(/\s+/g, ' ').trim().slice(0, 40) || f.name
390	  schedulePersist()
391	  emitFolders()
392	}
393	
394	export function deleteFolder(id: string): void {
395	  const list = allFolders()
396	  const idx = list.findIndex((f) => f.id === id)
397	  if (idx < 0) return
398	  list.splice(idx, 1)
399	  // 폴더에 속했던 대화는 미분류로
400	  let touched = false
401	  for (const c of all()) { if (c.folderId === id) { c.folderId = null; touched = true } }
402	  schedulePersist()
403	  emitFolders()
404	  if (touched) emitChanged()
405	}
406	
407	export function setConversationFolder(convId: string, folderId: string | null): void {
408	  const c = all().find((x) => x.id === convId)
409	  if (!c) return
410	  c.folderId = folderId && allFolders().some((f) => f.id === folderId) ? folderId : null
411	  schedulePersist()
412	  emitChanged()
413	}
414	
415	function sanitizeTags(tags: string[]): string[] {
416	  const out: string[] = []
417	  for (const raw of Array.isArray(tags) ? tags : []) {
418	    const t = String(raw ?? '').replace(/\s+/g, ' ').replace(/^#+/, '').trim().slice(0, MAX_TAG_LEN)
419	    if (t && !out.includes(t)) out.push(t)
420	    if (out.length >= MAX_TAGS) break
421	  }
422	  return out
423	}
424	
425	export function setConversationTags(convId: string, tags: string[]): void {
426	  const c = all().find((x) => x.id === convId)
427	  if (!c) return
428	  c.tags = sanitizeTags(tags)
429	  schedulePersist()
430	  emitChanged()
431	}
432	
433	// 모든 대화의 태그 합집합(필터 칩용)
434	export function listTags(): string[] {
435	  const set = new Set<string>()
436	  for (const c of all()) for (const t of c.tags ?? []) set.add(t)
437	  return Array.from(set).sort((a, b) => a.localeCompare(b, 'ko'))
438	}
