106	function summaryOf(r: AgentRun): AgentRunSummary {
107	  return { id: r.id, task: r.task, startedAt: r.startedAt, endedAt: r.endedAt, status: r.status, stepCount: r.steps.length }
108	}
109	
110	function emitChanged(): void {
111	  agentRunEvents.emit('changed', listAgentRuns())
112	}
113	
114	export function listAgentRuns(): AgentRunSummary[] {
115	  return all().slice().sort((a, b) => b.startedAt - a.startedAt).map(summaryOf)
116	}
