156	export function recordAgentEvent(runId: string, task: string, evt: EventLike): void {
157	  const list = all()
158	  let run = list.find((r) => r.id === runId)
159	
160	  if (evt.type === 'start') {
161	    if (run) return
162	    run = { id: runId, task: task || String(evt.task ?? '작업'), startedAt: Date.now(), status: 'running', steps: [] }
163	    list.unshift(run)
164	    if (list.length > MAX_RUNS) cache = list.slice(0, MAX_RUNS)
165	    schedulePersist(); emitChanged()
166	    return
167	  }
168	
169	  if (!run) {
170	    run = { id: runId, task: task || '작업', startedAt: Date.now(), status: 'running', steps: [] }
171	    list.unshift(run)
172	    if (list.length > MAX_RUNS) cache = list.slice(0, MAX_RUNS)
173	  }
174	
175	  if (evt.type === 'usage') {
176	    const n = (k: string): number => (typeof evt[k] === 'number' ? (evt[k] as number) : 0)
177	    const u = run.usage ?? { input: 0, cacheRead: 0, cacheCreate: 0, output: 0, llmCalls: 0 }
178	    u.input += n('input'); u.cacheRead += n('cacheRead'); u.cacheCreate += n('cacheCreate'); u.output += n('output'); u.llmCalls++
179	    run.usage = u
180	    schedulePersist()
181	    return
182	  }
183	
184	  const step = deriveStep(evt)
185	  if (step) {
186	    run.steps.push(step)
187	    // 상한 초과 시 최신(종료 마커 포함) 을 남기도록 오래된 단계를 버린다.
188	    if (run.steps.length > MAX_STEPS_PER_RUN) run.steps.splice(0, run.steps.length - MAX_STEPS_PER_RUN)
189	  }
190	
191	  let transitioned = false
192	  if (evt.type === 'done') { run.status = 'done'; run.endedAt = Date.now(); run.result = String(evt.message ?? ''); transitioned = true }
193	  else if (evt.type === 'error') { run.status = 'error'; run.endedAt = Date.now(); run.result = String(evt.message ?? ''); transitioned = true }
194	  else if (evt.type === 'cancelled') { run.status = 'cancelled'; run.endedAt = Date.now(); transitioned = true }
195	
196	  schedulePersist()
197	  if (transitioned) emitChanged() // 단계마다가 아니라 상태 전환 시에만 목록 갱신(라이브 트레이스는 별도 스트림)
198	}
199	
200	export function deleteAgentRun(id: string): void {
201	  const list = all()
202	  const idx = list.findIndex((r) => r.id === id)
203	  if (idx < 0) return
204	  list.splice(idx, 1)
205	  schedulePersist(); emitChanged()
206	}
207	
208	export function clearAgentRuns(): void {
209	  cache = []
210	  schedulePersist(); emitChanged()
211	}
