1494	      emit({ type: 'done', message: `${maxSteps}단계까지 시도했지만 완료하지 못했습니다. 더 구체적으로 지시하시거나, 막힌 부분을 직접 처리하신 뒤 이어서 지시해 주세요. (설정 > AI 에서 최대 단계 수를 늘릴 수도 있습니다.)`, ...(evidence ? { shot: evidence } : {}) })
1495	    }
1496	  } catch (err) {
1497	    emit({ type: 'error', message: friendlyError(err instanceof Error ? err.message : String(err)) })
1498	  } finally {
1499	    if (cli) { try { cli.close() } catch { /* ignore */ } cli = null }
1500	    activeCall.delete(reqId)
1501	    pendingConfirm.delete(reqId)
1502	    pendingAsk.delete(reqId)
1503	    cancelledSet.delete(reqId)
1504	    // 성공적으로 끝난 턴만 세션 맥락에 남긴다(다음 지시가 이어받도록).
1505	    if (recordOutcome !== null) {
1506	      const turns = agentSessions.get(sessionKey) ?? []
1507	      turns.push({ task, outcome: recordOutcome.slice(0, 300) })
1508	      while (turns.length > MAX_SESSION_TURNS) turns.shift()
1509	      agentSessions.set(sessionKey, turns)
1510	    }
1511	  }
1512	}
1513	
1514	// ===== 대량·반복 처리 — 데이터(CSV/목록) 각 행마다 같은 작업을 자동 반복하고 결과를 누적한다 =====
1515	
1516	const MAX_BATCH_ROWS = 100
1517	interface BatchState { cancelled: boolean; current: string | null }
1518	const batchState = new Map<string, BatchState>()
1519	
1520	export function cancelAgentBatch(reqId: string): void {
1521	  const b = batchState.get(reqId)
1522	  if (b) { b.cancelled = true; if (b.current) cancelAgentTask(b.current) }
1523	}
1524	
1525	// 작업 지시의 {열} 을 행 값으로 치환. 치환된 게 없으면 행 데이터를 뒤에 붙인다.
1526	function fillTemplate(task: string, row: Record<string, string>): string {
1527	  let used = false
1528	  const out = task.replace(/\{([^}]+)\}/g, (m, k: string) => {
1529	    const key = String(k).trim()
1530	    const hit = key in row ? key : Object.keys(row).find((kk) => kk.toLowerCase() === key.toLowerCase())
1531	    if (hit) { used = true; return row[hit] ?? '' }
1532	    return m
1533	  })
1534	  if (used) return out
1535	  const pairs = Object.entries(row).map(([k, v]) => `${k}=${v}`).join(', ')
1536	  return task + `\n\n[이번 데이터 행] ${pairs}`
1537	}
1538	
1539	export interface AgentBatchParams { reqId: string; tabId?: string; task: string; rows: Array<Record<string, string>>; autoConfirm?: boolean }
1540	
1541	export async function runAgentBatch(params: AgentBatchParams, emit: Emit): Promise<void> {
1542	  const rows = (params.rows || []).slice(0, MAX_BATCH_ROWS)
1543	  if (!rows.length) { emit({ type: 'error', message: '반복할 데이터 행이 없습니다.' }); return }
1544	  const st: BatchState = { cancelled: false, current: null }
1545	  batchState.set(params.reqId, st)
1546	  // 이 반복이 "계정 활동"(게시·댓글·팔로우·좋아요·DM)인지 — 행 간 간격을 사람 속도로 늦출지 판단한다.
1547	  const publishishTask = /게시|발행|올리|업로드|댓글|답글|좋아요|팔로우|구독|공유|보내|전송|post|publish|upload|comment|follow|like|share|send|dm/i.test(params.task)
1548	  emit({ type: 'batch-start', total: rows.length })
1549	  let completed = 0
1550	  try {
1551	    for (let i = 0; i < rows.length; i++) {
1552	      if (st.cancelled) { emit({ type: 'cancelled' }); break }
1553	      const row = rows[i] ?? {}
1554	      const task = fillTemplate(params.task, row)
1555	      emit({ type: 'batch-row', index: i, total: rows.length, row })
1556	      const sub = `${params.reqId}#${i}`
1557	      st.current = sub
1558	      let outcome = ''
1559	      // 무인 반복: 민감 동작은 autoConfirm 이면 승인, 아니면 그 행만 취소. 질문(ask)도 답할 수 없어 그 행 취소.
1560	      // 단 critical(결제·삭제 등 되돌릴 수 없는 것)은 autoConfirm 이어도 절대 자동 승인하지 않는다.
1561	      await runAgentTask({ reqId: sub, tabId: params.tabId, task, unattended: true }, (evt) => {
1562	        if (evt.type === 'done') { outcome = String(evt.message ?? '완료'); return }
1563	        if (evt.type === 'error') { outcome = '오류: ' + String(evt.message ?? ''); return }
1564	        if (evt.type === 'cancelled') { outcome = outcome || '건너뜀'; return }
1565	        if (evt.type === 'confirm') {
1566	          if (evt.critical) { outcome = `안전 중단: ${String(evt.label ?? '되돌릴 수 없는 동작')}`; cancelAgentTask(sub); return }
1567	          if (params.autoConfirm) confirmAgentStep(sub, true); else cancelAgentTask(sub)
1568	          return
1569	        }
1570	        if (evt.type === 'ask') { cancelAgentTask(sub); return }
1571	        // 진행 이벤트(observe/thought/action/result/extracted)는 행 번호를 달아 그대로 전달 → 트레이스·수집표 갱신.
1572	        emit({ ...evt, batchIndex: i })
1573	      })
1574	      st.current = null
1575	      completed++
1576	      emit({ type: 'batch-row-done', index: i, total: rows.length, outcome: outcome.slice(0, 200) })
1577	      // 행 사이 간격 — 예전에는 간격이 0이라 분당 수십 건 게시가 가능했고 그대로 스팸 판정·계정 정지로 이어졌다.
1578	      // 게시·댓글·팔로우처럼 계정 활동으로 집계되는 작업은 사람 속도(30~90초)로 늦추고, 조회·수집은 짧게만 쉰다.
1579	      if (i < rows.length - 1 && !st.cancelled) {
1580	        const gap = publishishTask
1581	          ? 30_000 + Math.floor(Math.random() * 60_000)
1582	          : 1_500 + Math.floor(Math.random() * 2_500)
1583	        if (publishishTask) emit({ type: 'result', ok: true, label: '다음 행 대기', detail: `계정 보호를 위해 ${Math.round(gap / 1000)}초 쉽니다(연속 게시 스팸 방지).` })
1584	        const step = 500
1585	        for (let waited = 0; waited < gap && !st.cancelled; waited += step) await new Promise((r) => setTimeout(r, Math.min(step, gap - waited)))
1586	      }
1587	    }
1588	    emit({ type: 'done', message: `대량 처리 완료 — ${completed}/${rows.length}개 행 처리${st.cancelled ? ' (중단됨)' : ''}.` })
1589	  } catch (err) {
1590	    emit({ type: 'error', message: friendlyError(err instanceof Error ? err.message : String(err)) })
1591	  } finally {
1592	    batchState.delete(params.reqId)
1593	  }
1594	}

