20	function resolveWindowId(e: IpcMainInvokeEvent, fallback: string | null = null): string | null {
21	  const wc = BrowserWindow.fromWebContents(e.sender)
22	  const ctxs = getAllWindows()
23	  for (const ctx of ctxs) {
24	    if (ctx.chrome.webContents.id === e.sender.id) return ctx.id
25	    if (wc && ctx.win === (wc as unknown as Electron.BaseWindow)) return ctx.id
26	  }
