13	const ASSET_MIME: Record<string, string> = {
14	  '.html': 'text/html; charset=utf-8',
15	  '.png': 'image/png',
16	  '.jpg': 'image/jpeg',
17	  '.jpeg': 'image/jpeg',
18	  '.webp': 'image/webp',
