28	async function handleBrowserUrl(request: Request): Promise<Response> {
29	  const url = new URL(request.url)
30	  const page = url.hostname
31	  if (!/^[a-z0-9-]+$/i.test(page)) {
32	    return new Response('Bad Request', { status: 400 })
33	  }
34	  // pathname 에서 페이지 폴더 내 단일 파일만 허용 (디렉터리·traversal 차단).
35	  // 빈 경로/`/` → index.html. 그 외엔 `pages/<page>/<file>` 로 정적 자산(이미지·css·js) 서빙.
36	  let rel = decodeURIComponent(url.pathname).replace(/^\/+/, '')
37	  if (rel === '') rel = 'index.html'
38	  const safe = /^[a-z0-9_.-]+$/i.test(rel) && !rel.includes('..')
39	  const ext = safe ? (rel.slice(rel.lastIndexOf('.')).toLowerCase()) : ''
40	  const pageDir = path.join(app.getAppPath(), 'pages', page)
41	  if (safe && ASSET_MIME[ext]) {
42	    try {
43	      const data = await fsPromises.readFile(path.join(pageDir, rel))
44	      return new Response(data, { headers: { 'Content-Type': ASSET_MIME[ext] } })
45	    } catch {
46	      // 자산이 없으면 — html 류는 index.html 폴백, 그 외(이미지 등)는 404
47	      if (ext !== '.html') {
48	        return new Response('Not Found', { status: 404, headers: { 'Content-Type': 'text/plain; charset=utf-8' } })
49	      }
50	    }
51	  }
52	  // 기본 동작: 페이지의 index.html (알 수 없는 경로도 index.html 로 — 기존 동작 보존)
53	  try {
54	    const data = await fsPromises.readFile(path.join(pageDir, 'index.html'))
55	    return new Response(data, { headers: { 'Content-Type': 'text/html; charset=utf-8' } })
56	  } catch {
57	    return new Response(`Not Found: browser://${page}`, {
58	      status: 404,
59	      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
60	    })
61	  }
62	}
