67	const installedSessionList: Session[] = []
68	const sessionHooks: Array<(ses: Session) => void> = []
69	
70	export function addSessionInitHook(hook: (ses: Session) => void): void {
71	  sessionHooks.push(hook)
72	  // 이미 install 된 모든 세션에도 즉시 적용
73	  for (const ses of installedSessionList) {
74	    try { hook(ses) } catch (err) { console.warn('[session-bootstrap] late hook failed', err) }
75	  }
76	}
77	
78	/** 설치된 세션 목록에서 제거 — 시크릿 창처럼 수명이 유한한(in-memory) 세션이 닫힌 뒤 누적되지 않도록.
79	 *  (영속 세션 persist:* 은 앱 수명 동안 유지되므로 호출하지 않는다.) */
80	export function removeInstalledSession(ses: Session): void {
81	  installedSessions.delete(ses)
82	  const i = installedSessionList.indexOf(ses)
83	  if (i >= 0) installedSessionList.splice(i, 1)
84	}
85	
86	/** 설치된 모든 세션을 순회 (adblock 재초기화 등에서 사용). */
87	export function forEachInstalledSession(fn: (ses: Session) => void): void {
88	  for (const ses of installedSessionList) {
89	    try { fn(ses) } catch (err) { console.warn('[session-bootstrap] forEach fn failed', err) }
90	  }
91	}
92	
93	export function setupSession(ses: Session): void {
94	  if (installedSessions.has(ses)) return
95	  installedSessions.add(ses)
96	  installedSessionList.push(ses)
97	
98	  // 1) browser:// 프로토콜
99	  try {
100	    ses.protocol.handle('browser', handleBrowserUrl)
101	  } catch (err) {
102	    // defaultSession 은 protocol.handle (global) 로 등록되어 이중 등록 시 throw — 안전 무시
103	    if (ses !== session.defaultSession) {
104	      console.warn('[session-bootstrap] protocol.handle failed', err)
105	    }
106	  }
107	
108	  // 2) 권한 핸들러 — 사이트별 오버라이드 우선 → policy 룰 → 화이트리스트 fallback
109	  ses.setPermissionRequestHandler((wc, perm, cb, details) => {
110	    const url = (details as { requestingUrl?: string })?.requestingUrl ?? wc?.getURL() ?? ''
111	    const site = url ? getPermissionDecision(url, perm) : null
112	    if (site === 'allow') return cb(true)
113	    if (site === 'deny') return cb(false)
114	    const decision = url ? permissionDecisionFor(url, perm) : null
115	    if (decision === 'allow') return cb(true)
116	    if (decision === 'deny') return cb(false)
117	    cb(PERMISSION_ALLOWED.includes(perm))
118	  })
119	  ses.setPermissionCheckHandler((wc, perm, requestingOrigin) => {
120	    const url = requestingOrigin || wc?.getURL() || ''
121	    const site = url ? getPermissionDecision(url, perm) : null
122	    if (site === 'allow') return true
123	    if (site === 'deny') return false
124	    const decision = url ? permissionDecisionFor(url, perm) : null
125	    if (decision === 'allow') return true
126	    if (decision === 'deny') return false
127	    return PERMISSION_ALLOWED.includes(perm)
128	  })
129	
130	  // 3) 미디어/토렌트 감지용 onResponseStarted (모든 세션에 설치 — 탭은 파티션 세션 사용)
131	  try { installResponseHooks(ses) } catch (err) { console.warn('[session-bootstrap] response-hooks failed', err) }
132	
133	  // 4) 외부 모듈 hook (policy webRequest, 향후 adblock 등)
134	  for (const hook of sessionHooks) {
135	    try { hook(ses) } catch (err) { console.warn('[session-bootstrap] hook failed', err) }
136	  }
137	}
138	
139	export function setupSessionByPartition(partition: string): void {
140	  const ses = session.fromPartition(partition)
141	  setupSession(ses)
142	}
