442	    for (const [k, v] of Object.entries(ep.headers)) request.setHeader(k, v)
443	
444	    request.on('response', (resp) => {
445	      const status = resp.statusCode ?? 0
446	      const errorChunks: Buffer[] = []
447	
448	      if (status < 200 || status >= 300) {
449	        resp.on('data', (c: Buffer) => errorChunks.push(c))
450	        resp.on('end', () => {
451	          finish(() => handlers.onError(friendlyError(req.provider, status, Buffer.concat(errorChunks).toString('utf8'))))
452	        })
453	        // 에러 본문 수신 중 연결이 끊기면 'error' 이벤트가 리스너 없이 throw 되므로 반드시 구독한다.
454	        resp.on('error', (err: Error) => finish(() => handlers.onError(err.message)))
