456	      }
457	
458	      const processLine = (line: string): void => {
459	        let parsed: { text?: string; done?: boolean } | null
460	        try {
461	          parsed = ep.parseLine(line)
462	        } catch (err) {
463	          finish(() => handlers.onError(err instanceof Error ? err.message : String(err)))
464	          try { request?.abort() } catch { /* ignore */ }
465	          return
466	        }
467	        if (!parsed) return
468	        if (parsed.text) {
469	          full += parsed.text
470	          handlers.onDelta(parsed.text)
471	        }
472	        if (parsed.done) {
473	          finish(() => handlers.onDone(full))
