482	        while ((idx = buffer.indexOf('\n')) >= 0) {
483	          const line = buffer.slice(0, idx)
484	          buffer = buffer.slice(idx + 1)
485	          processLine(line)
486	          if (finished) return
487	        }
488	      })
489	      resp.on('end', () => {
490	        if (buffer.trim()) processLine(buffer)
491	        finish(() => handlers.onDone(full))
492	      })
493	      resp.on('error', (err: Error) => {
494	        finish(() => handlers.onError(err.message))
495	      })
496	    })
