318	    if (spec.mode === 'outfile') outFile = join(tmpdir(), `bb-cli-${randomUUID()}.txt`)
319	    // 비전: claude-code 는 이미지를 임시 PNG 로 저장해 경로를 프롬프트에 넣으면 파일을 읽어 화면을 본다.
